#!/usr/bin/env node
/**
 * Plan phase 3, item 3.6 — render the app-identity PNGs from the approved RoomAI SVG masters
 * (public/brand/, exact originals; never redrawn). Everything this writes is regenerated by rerunning it:
 *
 *   node scripts/generate-app-assets.mjs            # writes public/icon-*.png and public/og-image.png
 *   PW_CHROMIUM=/path/to/chrome node scripts/generate-app-assets.mjs
 *
 * - icon-16/32/180/192/512.png: the approved app-icon tile exported at the sizes Logos.md names
 *   (16, 32, 180, 192, 512 — the 180 is the apple touch icon),
 * - icon-maskable-512.png: the same tile at 80% over its own night #10343F, so a circular mask never
 *   clips the arch (the maskable safe zone),
 * - og-image.png 1200×630: the approved cover art (components/Cover in the design package) with the
 *   full logo drawn from its outline SVG — no font loading, so the render is identical everywhere.
 *
 * Uses the project's Playwright chromium only as a renderer; no page is visited, no network is touched.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const PUB = join(ROOT, "public");

const appIcon = readFileSync(join(PUB, "brand", "roomai-app-icon.svg"), "utf8");
const fullLogo = readFileSync(join(PUB, "brand", "roomai-logo.svg"), "utf8");

/** The approved palette values (tokens.json, day) this composition uses. */
const NIGHT = "#10343F";
const SAND = "#F4EDE2";
const SPARK = "#0FA3B1";
const SAFFRON = "#D9952B";
const PAPER = "#FFFFFE";

function iconPage(svg, size, { scale = 1, background = "transparent" } = {}) {
  const inner = Math.round(size * scale);
  const off = Math.round((size - inner) / 2);
  const scaled = svg.replace(/width="64" height="64"/, `width="${inner}" height="${inner}"`);
  return `<!doctype html><html><body style="margin:0;width:${size}px;height:${size}px;background:${background}">
<div style="margin:${off}px;width:${inner}px;height:${inner}px">${scaled}</div></body></html>`;
}

/** The cover art from the approved Cover preview, scaled up from 960×288 to the 1200×630 share size. */
function ogPage() {
  return `<!doctype html><html><body style="margin:0;width:1200px;height:630px;background:${PAPER};overflow:hidden">
<div style="position:relative;width:1200px;height:630px">
  <svg viewBox="0 0 480 288" width="600" height="630" preserveAspectRatio="xMidYMid slice" style="position:absolute;top:0;left:600px">
    <rect fill="${NIGHT}" x="16" y="-36" width="256" height="300" rx="16"/>
    <path fill="${SAND}" d="M40 264V164A28 28 0 0 1 96 164V264Z"/>
    <path fill="${SAND}" d="M116 264V164A28 28 0 0 1 172 164V264Z"/>
    <path fill="${SAND}" d="M192 264V164A28 28 0 0 1 248 164V264Z"/>
    <path fill="${SPARK}" d="M144 182Q147.4 199.6 164 203Q147.4 206.4 144 224Q140.6 206.4 124 203Q140.6 199.6 144 182Z"/>
    <rect fill="${SAFFRON}" x="288" y="40" width="176" height="96" rx="16"/>
    <path fill="${SPARK}" d="M288 264V192A40 40 0 0 1 368 192V264Z"/>
  </svg>
  <div style="position:absolute;left:80px;top:50%;transform:translateY(-50%);width:460px">
    ${fullLogo.replace('width="256" height="72"', 'width="420" height="118"')}
  </div>
</div></body></html>`;
}

const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
const page = await browser.newPage();

async function render(html, size, out) {
  await page.setViewportSize({ width: size.width, height: size.height });
  await page.setContent(html, { waitUntil: "load" });
  const buf = await page.screenshot({ clip: { x: 0, y: 0, ...size } });
  writeFileSync(join(PUB, out), buf);
  console.log(`كتب ${out} (${size.width}×${size.height})`);
}

for (const size of [16, 32, 180, 192, 512]) {
  await render(iconPage(appIcon, size), { width: size, height: size }, `icon-${size}.png`);
}
await render(iconPage(appIcon, 512, { scale: 0.8, background: NIGHT }), { width: 512, height: 512 }, "icon-maskable-512.png");
await render(ogPage(), { width: 1200, height: 630 }, "og-image.png");

await browser.close();
console.log("اكتمل توليد ملفات البند 3.6 من الأصول المعتمدة.");
